function grade(q,arrows){const m=E2Drawing.models(q);return arrows.length===3&&q.moves.every(move=>arrows.some(a=>m.start.sources.find(s=>s.id===a.source)?.key===locKey(move.from)&&a.target===targetForMove(q,move)));}
function progress(){const qs=questions(),count=qs.filter(q=>done.has(q.id)).length;$('s-score').textContent=`Completed: ${count} / ${qs.length}`;$('s-progress').style.width=100*count/qs.length+'%';}
function board(){drawOrientation();if(!state.oriented){editor.setLocked(true);return;}const q=current(),m=E2Drawing.models(q),locked=state.arrowsCorrect;let html=E2Drawing.contents(q,m.start);for(const a of state.arrows){const s=m.start.sources.find(s=>s.id===a.source),t=m.start.targets.find(t=>t.key===a.target);html+=additionArrow(E2Drawing.route(q,s,t),s);}
if(!locked){if(selected){html+=m.start.targets.map(t=>`<circle class="s-hit" data-destination="${t.key}" cx="${t.x}" cy="${t.y}" r="20" tabindex="0" role="button" aria-label="Destination: ${esc(t.label)}"/>`).join('');html+=`<circle cx="${selected.x}" cy="${selected.y}" r="10" fill="none" stroke="#163d68" stroke-width="1.5"/><g id="s-live"></g>`;}else html+=m.start.sources.map(s=>`<circle class="s-hit" data-source="${s.id}" cx="${s.x}" cy="${s.y}" r="13" tabindex="0" role="button" aria-label="${esc(s.label)}"/>`).join('');}
$('s-start').innerHTML=`<svg id="s-board" class="sn2-board" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 520" role="group" aria-label="Starting materials. Place the three E2 electron-pair arrows."><g transform="translate(${m.tx} 0)">${html}</g></svg>`;const b=$('s-board');b.addEventListener('pointerdown',down);b.addEventListener('pointermove',motion);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',()=>{drag=null;});b.addEventListener('keydown',keyboard);
const hard=level==='hard'||level==='complete',shown=level==='easy'||state.arrowsCorrect;$('s-product').hidden=hard;$('p-editor').hidden=!hard;$('s-product').innerHTML=shown?E2Drawing.productSVG(q):'<div class="sn2-product-placeholder">The products will appear when all three arrows are correct.</div>';$('p-editor-section').hidden=!hard||!state.arrowsCorrect;$('p-drawing-help').hidden=!hard||!state.arrowsCorrect;$('p-editor-gate').hidden=state.arrowsCorrect;editor.setLocked(!hard||!state.arrowsCorrect||done.has(q.id));$('p-board').setAttribute('aria-disabled',String(editor.locked));$('p-board').setAttribute('tabindex',editor.locked?'-1':'0');$('s-check').disabled=state.arrowsCorrect;$('s-undo').disabled=state.arrowsCorrect||!state.arrows.length;$('s-clear').disabled=state.arrowsCorrect||(!state.arrows.length&&!selected);$('s-product-check').hidden=!hard||!state.arrowsCorrect;$('s-product-check').disabled=done.has(q.id);}
function begin(n=0){if(n<0||n>=questions().length)return;save();index=n;positions.set(level,index);const q=baseQuestion();active=q.id;state=clone(drafts.get(q.id)||fresh());selected=null;drag=null;picked=null;loading=true;editor.setLocked(false);editor.setGraph(state.graph,false);loading=false;$('s-count').textContent=`Question ${index+1} of ${questions().length}`;$('s-title').textContent=`Question ${index+1}: ${level==='complete'?'Reorient and React':'E2 Reaction'}`;$('s-question').value=index;$('s-prev').disabled=index===0;$('s-next').disabled=index===questions().length-1;$('s-help').textContent=level==='complete'?'Reorient the molecule to put a β-H antiperiplanar to the leaving group, add all three E2 arrows, then draw only the major alkene.':level==='easy'?'Choose a beta hydrogen antiperiplanar to the leaving group to form the major E2 elimination product. Place all three curly arrows; the products are shown.':level==='moderate'?'Identify a beta hydrogen antiperiplanar to the leaving group for the major E2 elimination pathway. Place all three arrows to reveal the products.':'Place the three arrows for the major E2 elimination pathway, then draw only the major alkene with the required geometry. The other species will appear automatically.';progress();board();tell(done.has(q.id)?'Correct. '+q.explanation:state.arrowsCorrect?'Correct arrows. Draw the main product in the box beside the reaction.':'',state.arrowsCorrect?'correct':'');}
function choose(next){if(!['easy','moderate','hard','complete'].includes(next))return;save();positions.set(level,index);active=null;level=next;index=positions.get(next)||0;document.querySelectorAll('[data-s-level]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.sLevel===level)));$('s-question').innerHTML=questions().map((q,i)=>`<option value="${i}">Question ${i+1}</option>`).join('');begin(index);}
function source(id){if(!state.oriented||state.arrowsCorrect)return;selected=E2Drawing.models(current()).start.sources.find(s=>s.id===id);if(!selected)return;tell('Choose the destination for this electron pair.');board();}
function destination(key){if(!selected||state.arrowsCorrect)return;if(!E2Drawing.models(current()).start.targets.some(t=>t.key===key))return;state.arrows.push({source:selected.id,target:key});selected=null;drag=null;save();board();tell(`${state.arrows.length} arrow${state.arrows.length===1?'':'s'} placed.`);}
function point(e){const p=new DOMPoint(e.clientX,e.clientY).matrixTransform($('s-board').getScreenCTM().inverse());return{x:p.x-E2Drawing.models(current()).tx,y:p.y};}function nearest(p){return E2Drawing.models(current()).start.targets.map(t=>({t,d:dist(t,p)})).filter(x=>x.d<25).sort((a,b)=>a.d-b.d)[0]?.t;}
function down(e){if(state.arrowsCorrect||e.button>0)return;if(e.target.dataset.source){const p=point(e);source(e.target.dataset.source);drag={id:e.pointerId,start:p,moved:false};$('s-board').setPointerCapture?.(e.pointerId);e.preventDefault();}else if(e.target.dataset.destination){destination(e.target.dataset.destination);e.preventDefault();}}
