 $('eo-check').hidden=state.oriented;$('eo-clear').hidden=state.oriented;$('s-check').hidden=!state.oriented||state.arrowsCorrect;$('s-product-check').hidden=!state.arrowsCorrect;$('s-undo').hidden=!state.oriented||state.arrowsCorrect;$('s-clear').hidden=!state.oriented||state.arrowsCorrect;
 if(state.oriented)return;
 $('p-editor-section').hidden=true;$('p-drawing-help').hidden=true;
 $('eo-source').innerHTML=E2Orientation.diagram(q,[...q.sourceA,...q.sourceB]);$('eo-target').innerHTML=E2Orientation.diagram(q,state.placed.map(p=>p?.value),true,false,true);
