$('eo-check').addEventListener('click',checkOrientation);$('eo-clear').addEventListener('click',()=>{if(state.oriented)return;state.placed=Array(6).fill(null);picked=null;save();board();tell('');});
$('eo-pieces').addEventListener('click',e=>{const b=e.target.closest('[data-eo-piece]');if(!b||b.disabled)return;picked=picked===+b.dataset.eoPiece?null:+b.dataset.eoPiece;board();$('eo-pieces').querySelector('[data-eo-piece="'+b.dataset.eoPiece+'"]')?.focus();});
